/*! 樱雾 · Sakura Mist v1.0.0 — generated by build.mjs; edit src/ instead. */
window.__ModuleLoader__.load({
    id: "dsh-theme-sakura-mist",
    factory: (require) => {
        var module = { exports: {} };
        var exports = module.exports;
        Object.defineProperty(exports, Symbol.toStringTag, { value: "Module" });

        const __SAKURA_VERSION__ = "1.0.0";
        const __SAKURA_CSS__ = "/* ==========================================================================\n   樱雾 · Sakura Mist — 粉色护眼美化材质 for DeepSeek Harness\n   --------------------------------------------------------------------------\n   设计目标：朴素、圆角、高级质感、护眼。\n   · 护眼：暖玫瑰纸色而非纯白，暖墨色而非纯黑；低饱和；对比度约 12–14:1。\n   · 朴素：粉只作为底色与强调的“气味”，不铺满；功能色（成功/警告/错误）照常。\n   · 圆角：半径整体放大 + superellipse 圆角形状，形成圆润的“石子”质感。\n   · 质感：暖调分层阴影、发丝描边、极淡纸纹与柔光，菜单雾面磨砂。\n   用法：由客户端插件注入（html.dsh-sakura-mist），卸载时整体移除，可安全回滚。\n   注：本文件位于 ~/.dsh/themes/，不随 DSH 应用升级被覆盖。\n   ========================================================================== */\n\n/* --------------------------------------------------------------------------\n   0. 自身调色板（仅供本文件引用，避免与 DSH 变量冲突）\n   -------------------------------------------------------------------------- */\nhtml.dsh-sakura-mist {\n  --sakura-ink: #2c211d;\n  --sakura-ink-soft: #463530;\n  --sakura-rose: #ad6277;\n  --sakura-rose-deep: #945063;\n  --sakura-rose-light: #d48e9f;\n  --sakura-paper: #f9f3ef;\n  --sakura-paper-hi: #fffdfb;\n  --sakura-hairline: #7a4f4714;\n  --sakura-shadow: #5e37311a;\n  --sakura-glow: #ffd7dc;\n  --sakura-selection: #c9809a47;\n}\n\n/* --------------------------------------------------------------------------\n   1. 形状与质感：圆角刻度、superellipse、焦点环、阴影阶梯\n      —— 主题无关，深浅两色共用。\n   -------------------------------------------------------------------------- */\nhtml.dsh-sakura-mist {\n  /* 圆角：比默认整体大一号，保持克制（朴素，不玩具化） */\n  --dsw-radius-xs: 6px;\n  --dsw-radius-sm: 10px;\n  --dsw-radius-md: 14px;\n  --dsw-radius-lg: 20px;\n  --dsw-radius-xl: 26px;\n  --dsw-radius-panel: 32px;\n\n  /* 圆角形状：DSH 在支持 corner-shape 的引擎里应用到全部元素 */\n  --dsw-corner-shape: superellipse(1.62);\n\n  /* 焦点环：玫瑰棕，2px 标准宽度（护眼：不刺眼的可见性） */\n  --dsw-focus-ring-color: #b06074;\n  --dsw-focus-ring-width: 2px;\n\n  /* 阴影：暖褐投影 + 发丝内描边，替代纯黑硬阴影 */\n  --dsw-shadow-lv1: 0 1px 2px 0 #5e37310f, 0 2px 6px 0 #5e373109;\n  --dsw-shadow-lv1-blur: 0 4px 14px 0 #5e373109;\n  --dsw-shadow-lv2: 0 2px 6px 0 #5e373110, 0 6px 18px 0 #5e37310d;\n  --dsw-shadow-lv3: 0 0 1px 0 #5e373128, 0 10px 30px 0 #5e37311a, 0 2px 8px 0 #5e37310f;\n\n  --dsw-elevation-stroke: 0 0 0 0.5px var(--dsw-elevation-stroke-color);\n  --dsw-elevation-panel: var(--dsw-elevation-stroke), 0 4px 10px 0 #5e37310b, 0 0 18px 0 #5e373107;\n  --dsw-elevation-prominent: var(--dsw-elevation-stroke), 0 4px 12px 0 #5e373110, 0 0 24px 0 #5e37310f;\n  --dsw-elevation-soft: var(--dsw-elevation-stroke), 0 6px 22px 0 #5e37310b, 0 0 28px 0 #5e373109;\n\n  /* 雾面材质：更柔和的磨砂，减少“玻璃感”的廉价高饱和 */\n  --dsw-menu-backdrop-filter: blur(30px) saturate(122%);\n}\n\n/* --------------------------------------------------------------------------\n   2. 冷暖中性色阶：一次替换，深浅两套别名都会自动跟随（DSH 的 static 色阶\n      与主题无关，浅色别名取亮端、深色别名取暗端）。全部偏暖、低饱和。\n   -------------------------------------------------------------------------- */\nhtml.dsh-sakura-mist.dsh-sakura-mist body,\nhtml.dsh-sakura-mist.dsh-sakura-mist body[data-ds-dark-theme] {\n  /* 主中性阶：纸白 → 暖墨（暗端带一点樱灰紫，暮色里保留粉色记忆） */\n  --dsw-static-neutral-bluish-00: #fffcfb;\n  --dsw-static-neutral-bluish-50: #faf2f0;\n  --dsw-static-neutral-bluish-60: #f6ece9;\n  --dsw-static-neutral-bluish-75: #f2e5e1;\n  --dsw-static-neutral-bluish-100: #ecddd8;\n  --dsw-static-neutral-bluish-150: #e6d4ce;\n  --dsw-static-neutral-bluish-200: #decac4;\n  --dsw-static-neutral-bluish-300: #cbb2ac;\n  --dsw-static-neutral-bluish-400: #b0948e;\n  --dsw-static-neutral-bluish-500: #977a76;\n  --dsw-static-neutral-bluish-600: #7e645f;\n  --dsw-static-neutral-bluish-700: #66504c;\n  --dsw-static-neutral-bluish-750: #594440;\n  --dsw-static-neutral-bluish-800: #4a3733;\n  --dsw-static-neutral-bluish-850: #3d2b28;\n  --dsw-static-neutral-bluish-875: #342428;\n  --dsw-static-neutral-bluish-900: #2b1d21;\n  --dsw-static-neutral-bluish-950: #22161a;\n  --dsw-static-neutral-bluish-1000: #191011;\n\n  /* 代码 / 滚动条用的第二中性阶：同样暖化，彼此可分辨 */\n  --dsw-static-neutral-00: #fffcfb;\n  --dsw-static-neutral-50: #faf4f1;\n  --dsw-static-neutral-100: #f4ebe7;\n  --dsw-static-neutral-150: #eee2dd;\n  --dsw-static-neutral-200: #e6d8d3;\n  --dsw-static-neutral-250: #decec9;\n  --dsw-static-neutral-300: #d1bdb8;\n  --dsw-static-neutral-400: #a88f8a;\n  --dsw-static-neutral-500: #8b726e;\n  --dsw-static-neutral-550: #715a56;\n  --dsw-static-neutral-600: #5a4642;\n  --dsw-static-neutral-700: #43322f;\n  --dsw-static-neutral-800: #2f2321;\n  --dsw-static-neutral-850: #271c1b;\n  --dsw-static-neutral-900: #1b1314;\n  --dsw-static-neutral-1000: #120c0d;\n\n  /* 品牌强调：把 DSH 的深蓝换成低饱和的玫瑰（仍保留层级语义） */\n  --dsw-static-deepseek-50: #fceff1;\n  --dsw-static-deepseek-100: #f9e0e4;\n  --dsw-static-deepseek-200: #f3cbd2;\n  --dsw-static-deepseek-300: #e7afbb;\n  --dsw-static-deepseek-400: #d48e9f;\n  --dsw-static-deepseek-450: #c37e92;\n  --dsw-static-deepseek-500: #ad6277;\n  --dsw-static-deepseek-600: #945063;\n  --dsw-static-deepseek-700-delete: #7a4152;\n  --dsw-static-deepseek-800: #5c303d;\n  --dsw-static-deepseek-900: #45242e;\n\n  /* 功能色：保留语义，但降饱和、偏暖，避免刺眼 */\n  --dsw-static-red-50: #fcf1f0;\n  --dsw-static-red-100: #fbe3e1;\n  --dsw-static-red-400: #d97770;\n  --dsw-static-red-400-a12: #d9777020;\n  --dsw-static-red-500: #c25b55;\n  --dsw-static-red-600: #a9443f;\n  --dsw-static-red-600-a08: #a9443f14;\n  --dsw-static-red-900: #4e1e1b;\n  --dsw-static-green-100: #e7f3ea;\n  --dsw-static-green-400: #6fbe8a;\n  --dsw-static-green-500: #4ea573;\n  --dsw-static-green-500-a08: #4ea57314;\n  --dsw-static-green-500-a12: #4ea5731f;\n  --dsw-static-green-900: #1f3a2a;\n  --dsw-static-amber-100: #faf1e1;\n  --dsw-static-amber-400: #dfa85c;\n  --dsw-static-amber-500: #ce9443;\n  --dsw-static-amber-600: #b47b33;\n  --dsw-static-amber-900: #3a2c1b;\n}\n\n/* --------------------------------------------------------------------------\n   3. 浅色纸感：底色是极浅的玫瑰纸，卡片是暖象牙白，靠发丝线分层\n   -------------------------------------------------------------------------- */\nhtml.dsh-sakura-mist.dsh-sakura-mist body:not([data-ds-dark-theme]) {\n  --dsw-alias-bg-base: #fbf6f3;\n  --dsw-alias-bg-layer-1: #fffdfb;\n  --dsw-alias-bg-layer-2: #fdf7f4;\n  --dsw-alias-bg-layer-3: #f8f0eb;\n  --dsw-alias-bg-overlay: #ede2db;\n  --dsw-alias-bg-module-platform: #f6ece6;\n  --dsw-alias-bg-multi-select: #f6ece6;\n  --dsw-alias-bg-document-preview: #f3e9e3;\n\n  /* 文字：暖墨，避免纯黑的“硬” */\n  --dsw-alias-label-primary: #2c201b;\n  --dsw-alias-label-primary-dimmed: #463530;\n  --dsw-alias-label-secondary: #5f4a42;\n  --dsw-alias-label-tertiary: #7d655c;\n  --dsw-alias-label-caption: #9a7f75;\n  --dsw-alias-label-dimmed: #e3d3cb;\n  --dsw-alias-label-document-preview: #5f4a42;\n  --dsw-alias-menu-icon: #46322c;\n\n  /* 发丝描边：暖玫瑰棕的半透明，比纯黑描边更有材质感 */\n  --dsw-alias-border-l1: #7a4f4718;\n  --dsw-alias-border-l2: #7a4f4724;\n  --dsw-alias-border-l3: #7a4f473d;\n  --dsw-alias-border-l4: #7a4f4740;\n  --dsw-alias-border-l2-darkmode-thin: #7a4f4724;\n\n  /* 交互层：玫瑰色的悬停与按下，弱到不影响阅读 */\n  --dsw-alias-interactive-bg-hover: #8a5a5f1a;\n  --dsw-alias-interactive-bg-active: #8a5a5f2b;\n  --dsw-alias-interactive-bg-hover-accent: #8a5a5f2b;\n  --dsw-alias-interactive-bg-hover-solid: #f0e2db;\n  --dsw-alias-bg-skeleton: #6b403d0d;\n\n  /* 菜单 / 浮层：暖象牙雾面，比默认更不透明以便长时间阅读 */\n  --dsw-menu-surface-fill: #fcf6f2f0;\n  --dsw-specific-menu: #fcf6f2f0;\n  --dsw-alias-menu-group-header-fill: #f9f2edf7;\n  --dsw-alias-toast-bg: #4a3630;\n  --dsw-alias-toast-label: #fffdfb;\n  --dsw-alias-tooltip-bg: #3d2b25;\n  --dsw-alias-tooltip-key-bg: color-mix(in srgb, var(--dsw-alias-tooltip-bg), #ffd7dc 16%);\n\n  /* 对话气泡、输入区、侧栏：粉只出现在“用户自己的话”上 */\n  --dsw-specific-bubble: #fbe8eb;\n  --dsw-specific-bubble-highlight: #f2c9d1;\n  --dsw-specific-input-major: #fffdfb;\n  --dsw-specific-login-input: #faf3ee;\n  --dsw-specific-selector: #f6ece6;\n  --dsw-specific-sidebar-fill: #f4e9e3;\n  --dsw-specific-sidebar-nav-item-active: #efd9d6;\n  --dsw-specific-sidebar-nav-item-hover: #f0e0da;\n  --dsw-specific-sidebar-nav-item-active-accent: #f9e0e4;\n  --dsw-specific-tip: #f6ece6;\n\n  /* 代码块：暖纸底，和正文纸色分开但不过度对比 */\n  --dsw-alias-markdown-code-block: #f7eee8;\n  --dsw-alias-markdown-code-block-banner: #f4e9e2;\n  --dsw-alias-markdown-inline-code: #f4eae3;\n  --dsw-alias-markdown-citation: #f2e6df;\n  --dsw-alias-markdown-placeholder: #f6ece6;\n  --dsw-alias-markdown-tag: #f2e6df;\n  --dsw-alias-markdown-code-segment-selected: #fffdfb;\n  --dsw-alias-markdown-code-segment-unselected: #f2e6df;\n\n  /* 强调与状态 */\n  --dsw-alias-brand-primary-new-colorprimary-new-color: #ad6277;\n  --dsw-alias-state-business-primary: #ad6277;\n  --dsw-alias-state-business-tertiary: #f9e0e4;\n  --dsw-alias-link: #a35a6f;\n  --dsw-alias-label-deep-diving: color-mix(in srgb, #ad6277 70%, #45242e);\n  --dsw-alias-label-deep-diving-shimmer: color-mix(in srgb, #c37e92 34%, #45242e);\n\n  /* 选择与滚动条：选区需要一眼可辨，但仍保持柔和 */\n  --dsw-alias-bg-document-selection: #c97e9673;\n  --dsw-alias-scrollbar-bg-l1: #cbb2aa;\n  --dsw-alias-scrollbar-bg-l2: #cbb2aa;\n  --dsw-alias-scrollbar-hover-l1: #b89b92;\n  --dsw-alias-scrollbar-hover-l2: #b89b92;\n\n  /* 设置卡片 */\n  --dsw-alias-settings-card-fill: var(--dsw-alias-bg-layer-2);\n  --dsw-alias-settings-card-stroke: var(--dsw-alias-border-l4);\n}\n\n/* --------------------------------------------------------------------------\n   4. 深色暮樱：暖紫褐夜色 + 奶油色文字，避免蓝黑与纯白的高对比\n   -------------------------------------------------------------------------- */\nhtml.dsh-sakura-mist.dsh-sakura-mist body[data-ds-dark-theme] {\n  --dsw-alias-bg-base: #241a1d;\n  --dsw-alias-bg-layer-1: #2b1e23;\n  --dsw-alias-bg-layer-2: #312227;\n  --dsw-alias-bg-layer-3: #37272c;\n  --dsw-alias-bg-overlay: #594440;\n  --dsw-alias-bg-document-preview: #22161a;\n  --dsw-alias-bg-module-platform: #4a3733;\n  --dsw-alias-bg-multi-select: #271c1b;\n\n  --dsw-alias-label-primary: #f3e8ea;\n  --dsw-alias-label-primary-dimmed: #e4d5d9;\n  --dsw-alias-label-secondary: #d8c4c8;\n  --dsw-alias-label-tertiary: #c6aeb4;\n  --dsw-alias-label-caption: #a69096;\n  --dsw-alias-label-dimmed: #6a534e;\n  --dsw-alias-label-document-preview: #cbb2ac;\n  --dsw-alias-menu-icon: #e4d5d9;\n\n  --dsw-alias-border-inverted: #f6e4e817;\n  --dsw-alias-border-inverted2: #f6e4e81c;\n  --dsw-alias-border-l1: #f6e4e817;\n  --dsw-alias-border-l2: #f6e4e824;\n  --dsw-alias-border-l3: #f6e4e83d;\n  --dsw-alias-border-l4: #f6e4e83d;\n  --dsw-alias-border-l2-darkmode-thin: #f6e4e817;\n\n  --dsw-alias-interactive-bg-hover: #f6e4e81c;\n  --dsw-alias-interactive-bg-active: #f6e4e82e;\n  --dsw-alias-interactive-bg-hover-accent: #f6e4e842;\n  --dsw-alias-interactive-bg-hover-danger: #e08a8a26;\n  --dsw-alias-interactive-bg-hover-solid: #4a3733;\n  --dsw-alias-bg-skeleton: #f6e4e814;\n\n  --dsw-menu-surface-fill: #33242aea;\n  --dsw-specific-menu: #33242aea;\n  --dsw-alias-menu-group-header-fill: #382930f2;\n  --dsw-alias-toast-bg: #4a3733;\n  --dsw-alias-toast-label: #fffcfb;\n  --dsw-alias-tooltip-bg: #4a3733;\n  --dsw-alias-tooltip-key-bg: color-mix(in srgb, var(--dsw-alias-tooltip-bg), #ffd7dc 16%);\n\n  --dsw-specific-bubble: #3c262e;\n  --dsw-specific-bubble-highlight: #594440;\n  --dsw-specific-input-major: #2e2025;\n  --dsw-specific-login-input: #22161a;\n  --dsw-specific-selector: #4a3733;\n  --dsw-specific-sidebar-fill: #180f12;\n  --dsw-specific-sidebar-nav-item-active: #422a31;\n  --dsw-specific-sidebar-nav-item-hover: #35242a;\n  --dsw-specific-sidebar-nav-item-active-accent: #5c2f3f;\n  --dsw-specific-tip: #4a3733;\n\n  --dsw-alias-markdown-code-block: #2a1c21;\n  --dsw-alias-markdown-code-block-banner: #322329;\n  --dsw-alias-markdown-inline-code: #322329;\n  --dsw-alias-markdown-citation: #4a3733;\n  --dsw-alias-markdown-placeholder: #3d2b25;\n  --dsw-alias-markdown-tag: #3d2b25;\n  --dsw-alias-markdown-code-segment-selected: #4a3733;\n  --dsw-alias-markdown-code-segment-unselected: #2b1d21;\n\n  --dsw-alias-brand-primary-new-colorprimary-new-color: #d48e9f;\n  --dsw-alias-state-business-primary: #d48e9f;\n  --dsw-alias-state-business-tertiary: #5c303d;\n  --dsw-alias-link: #d48e9f;\n  --dsw-alias-label-deep-diving: color-mix(in srgb, #d48e9f 58%, #b0968b);\n  --dsw-alias-label-deep-diving-shimmer: color-mix(in srgb, #e7afbb 62%, #d48e9f);\n\n  --dsw-alias-bg-document-selection: #d896a666;\n  --dsw-alias-scrollbar-bg-l1: #4a3733;\n  --dsw-alias-scrollbar-bg-l2: #5a463f;\n  --dsw-alias-scrollbar-hover-l1: #5a463f;\n  --dsw-alias-scrollbar-hover-l2: #715a51;\n\n  --dsw-alias-settings-card-fill: var(--dsw-alias-bg-layer-2);\n  --dsw-alias-settings-card-stroke: var(--dsw-alias-border-l4);\n\n  /* 深色下的阴影需要用更深的暖黑，才压得住亮起的层 */\n  --dsw-shadow-lv1: 0 1px 2px 0 #00000038, 0 2px 8px 0 #00000024;\n  --dsw-shadow-lv1-blur: 0 4px 16px 0 #00000024;\n  --dsw-shadow-lv2: 0 2px 8px 0 #00000038, 0 8px 22px 0 #0000002b;\n  --dsw-shadow-lv3: 0 0 1px 0 #00000059, 0 12px 36px 0 #00000047, 0 2px 10px 0 #00000033;\n  --dsw-elevation-stroke-color: #f6e4e830;\n\n  --dsw-focus-ring-color: #d79cac;\n}\n\n/* macOS 的菜单材质是单独一条更高优先级的规则，这里把它拉回同一套雾面 */\nhtml.dsh-sakura-mist.dsh-sakura-mist[data-platform=\"darwin\"] body {\n  --dsw-specific-menu: #fcf6f2f0;\n}\nhtml.dsh-sakura-mist.dsh-sakura-mist[data-platform=\"darwin\"] body[data-ds-dark-theme] {\n  --dsw-specific-menu: #33242af2;\n}\n\n/* --------------------------------------------------------------------------\n   5. 材质覆层：极淡纸纹 + 两团柔光（只在视觉上叠一层“纸”), 不拦截交互\n   -------------------------------------------------------------------------- */\nhtml.dsh-sakura-mist body::after {\n  content: \"\";\n  position: fixed;\n  inset: 0;\n  z-index: 2147483646;\n  pointer-events: none;\n  opacity: 0.5;\n  background-image:\n    url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.86' numOctaves='3' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/></filter><rect width='160' height='160' filter='url(%23n)' opacity='0.075'/></svg>\"),\n    radial-gradient(1100px 560px at 6% -14%, #ffd3da26 0%, rgba(255, 211, 218, 0) 62%),\n    radial-gradient(900px 520px at 104% -6%, #ffe4cf1f 0%, rgba(255, 228, 207, 0) 58%);\n  background-size: 160px 160px, 100% 100%, 100% 100%;\n  background-repeat: repeat, no-repeat, no-repeat;\n}\nhtml.dsh-sakura-mist body[data-ds-dark-theme]::after {\n  opacity: 0.42;\n  background-image:\n    url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.86' numOctaves='3' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/></filter><rect width='160' height='160' filter='url(%23n)' opacity='0.07'/></svg>\"),\n    radial-gradient(1100px 560px at 8% -14%, #ff9fb926 0%, rgba(255, 159, 185, 0) 60%),\n    radial-gradient(900px 520px at 102% -4%, #ffb08f1a 0%, rgba(255, 176, 143, 0) 56%);\n}\n\n/* --------------------------------------------------------------------------\n   6. 区域分隔：侧栏列与对话列之间给出清晰的材质边界\n      DSH 的侧栏列类名形如 `<hash>_sidebarCol`，用属性包含选择器稳定命中；\n      只用内阴影画分隔线，不改动布局尺寸。\n   -------------------------------------------------------------------------- */\nhtml.dsh-sakura-mist [class*=\"_sidebarCol\"] {\n  --sakura-divider: #7a4f4733;\n  box-shadow:\n    inset -1px 0 0 0 var(--sakura-divider),\n    inset -14px 0 22px -20px #5e373126,\n    inset 0 1px 0 0 #ffffff40;\n}\nhtml.dsh-sakura-mist body[data-ds-dark-theme] [class*=\"_sidebarCol\"] {\n  --sakura-divider: #f6e4e83d;\n  box-shadow:\n    inset -1px 0 0 0 var(--sakura-divider),\n    inset -14px 0 22px -20px #00000073,\n    inset 0 1px 0 0 #f6e4e814;\n}\n/* 对话列左侧再压一点纵深，两列一眼可分 */\nhtml.dsh-sakura-mist [class*=\"_centerCol\"] {\n  box-shadow: inset 14px 0 22px -24px #5e37312e;\n}\nhtml.dsh-sakura-mist body[data-ds-dark-theme] [class*=\"_centerCol\"] {\n  box-shadow: inset 14px 0 22px -24px #0000008c;\n}\n\n/* --------------------------------------------------------------------------\n   7. 细节：选区、滚动条、焦点环的玫瑰化\n   -------------------------------------------------------------------------- */\n/* 长按拖选：选区要“一眼可辨”，用 40%–45% 的玫瑰色底，文字仍用主文字色保证清晰 */\nhtml.dsh-sakura-mist body ::selection,\nhtml.dsh-sakura-mist body::selection {\n  background-color: var(--dsw-alias-bg-document-selection);\n  color: var(--dsw-alias-label-primary);\n}\nhtml.dsh-sakura-mist body[data-ds-dark-theme] ::selection,\nhtml.dsh-sakura-mist body[data-ds-dark-theme]::selection {\n  background-color: var(--dsw-alias-bg-document-selection);\n  color: var(--dsw-alias-label-primary);\n}\n\nhtml.dsh-sakura-mist ::-webkit-scrollbar-thumb {\n  border-radius: 999px;\n}\nhtml.dsh-sakura-mist ::-webkit-scrollbar-corner {\n  background: transparent;\n}\n\n/* --------------------------------------------------------------------------\n   8. 数学公式回退（KaTeX 解析失败）：\n      框架把回退文本写死成内联 `color:#cc0000`，在任何底色上都过于扎眼。\n      这里用 !important 压成柔和的砖粉 / 灰玫，保留“这是回退源文”的提示，\n      但把饱和度与亮度降下来，不再抢走视线。\n   -------------------------------------------------------------------------- */\nhtml.dsh-sakura-mist .katex-error {\n  color: #b1746e !important;\n  opacity: 0.9;\n}\nhtml.dsh-sakura-mist body[data-ds-dark-theme] .katex-error {\n  color: #c9918c !important;\n  opacity: 0.9;\n}\n";

    /**
     * 樱雾 · Sakura Mist —— 浏览器侧插件主体（由 build.mjs 包进 __ModuleLoader__）
     *
     * 这段代码不是独立模块：它运行在 client bundle 的 factory 里，可直接使用上方
     * 注入的 __SAKURA_CSS__ 常量；末尾由 build.mjs 补上 `exports.apply = apply`。
     *
     * 行为：
     *  1. 把主题样式表以 constructable stylesheet 挂到 document（回退到 <style>）；
     *  2. 给 <html> 加 dsh-sakura-mist 类，作为全部覆盖规则的作用域；
     *  3. 样式生效后向宿主 /sakura-mist/beacon 发一次回执，附带页面上实测到的令牌值，
     *     便于无 DevTools 时确认主题真的应用到了当前窗口；
     *  4. 卸载（插件禁用 / HMR 替换）时完整回滚，界面立刻恢复原样。
     */
    
    const ROOT_CLASS = 'dsh-sakura-mist'
    const THEME_ID = 'sakura-mist'
    const STYLE_KEY = 'data-dsh-sakura-mist'
    
    /** 回执里抽查的令牌：覆盖底色、卡片、正文、边框、强调、圆角、气泡。 */
    const PROBE_TOKENS = [
      '--dsw-alias-bg-base',
      '--dsw-alias-bg-layer-1',
      '--dsw-alias-label-primary',
      '--dsw-alias-border-l4',
      '--dsw-alias-state-business-primary',
      '--dsw-radius-lg',
      '--dsw-specific-bubble',
      '--dsw-alias-bg-document-selection',
    ]
    
    function readProbe() {
      const probe = {}
      try {
        const styles = getComputedStyle(document.body)
        for (const token of PROBE_TOKENS) probe[token] = styles.getPropertyValue(token).trim()
      } catch {}
      return probe
    }
    
    function installStyleElement(css) {
      const element = document.createElement('style')
      element.setAttribute(STYLE_KEY, THEME_ID)
      element.textContent = css
      document.head.appendChild(element)
      return () => {
        element.remove()
      }
    }
    
    function installAdoptedSheet(css) {
      if (typeof CSSStyleSheet === 'undefined' || !('adoptedStyleSheets' in document)) return null
      try {
        const sheet = new CSSStyleSheet()
        sheet.replaceSync(css)
        const before = document.adoptedStyleSheets
        document.adoptedStyleSheets = [...before, sheet]
        return () => {
          document.adoptedStyleSheets = document.adoptedStyleSheets.filter((item) => item !== sheet)
        }
      } catch {
        return null
      }
    }
    
    function sendBeacon(payload) {
      try {
        fetch('/sakura-mist/beacon', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify(payload),
          keepalive: true,
        }).catch(() => {})
      } catch {
        // 回执失败不影响主题
      }
    }
    
    function apply(ctx) {
      ctx.effect(() => {
        const root = document.documentElement
        const removeAdopted = installAdoptedSheet(__SAKURA_CSS__)
        const removeElement = removeAdopted === null ? installStyleElement(__SAKURA_CSS__) : null
        root.classList.add(ROOT_CLASS)
        root.setAttribute('data-dsh-theme', THEME_ID)
    
        const startedAt = Date.now()
        const report = () => {
          const dark = document.body?.hasAttribute('data-ds-dark-theme') === true
          sendBeacon({
            theme: THEME_ID,
            version: __SAKURA_VERSION__,
            dark,
            url: location.href,
            title: document.title,
            viewport: { width: innerWidth, height: innerHeight, dpr: devicePixelRatio },
            appliedMs: Date.now() - startedAt,
            tokens: readProbe(),
          })
        }
        // 等主题 presenter 写完 body 的深色标记与令牌，再回执一次实测值。
        const timer = setTimeout(report, 700)
    
        return () => {
          clearTimeout(timer)
          removeAdopted?.()
          removeElement?.()
          root.classList.remove(ROOT_CLASS)
          root.removeAttribute('data-dsh-theme')
        }
      }, 'sakura-mist: theme stylesheet')
    }
    
    function disposeStyles() {
      // 兜底：effect 未建立前的异常路径不留下半套样式。
      for (const element of document.querySelectorAll(`style[${STYLE_KEY}]`)) element.remove()
      document.documentElement.classList.remove(ROOT_CLASS)
    }
    
    // build.mjs 在此之后补上 `exports.apply = apply` / `exports.disposeStyles = ...`。
    

        exports.name = "sakura-mist-theme";
        exports.apply = apply;
        exports.disposeStyles = disposeStyles;
        return module.exports;
    }
});

